import sys
input = sys.stdin.read
data = input().split()

row1 = data[0]
row2 = data[1]
n = len(row1)

def can_place_bishwock(r1, r2, pos, pattern):
    if pattern == 0:
        if pos < n - 1 and r1[pos] == '0' and r1[pos + 1] == '0' and r2[pos] == '0':
            return True
    elif pattern == 1:
        if pos < n - 1 and r2[pos] == '0' and r2[pos + 1] == '0' and r1[pos] == '0':
            return True
    elif pattern == 2:
        if pos < n - 1 and r1[pos] == '0' and r2[pos] == '0' and r2[pos + 1] == '0':
            return True
    elif pattern == 3:
        if pos < n - 1 and r1[pos] == '0' and r1[pos + 1] == '0' and r2[pos + 1] == '0':
            return True
    return False

def place_bishwock(r1, r2, pos, pattern):
    if pattern == 0:
        r1[pos] = r1[pos + 1] = r2[pos] = 'X'
    elif pattern == 1:
        r2[pos] = r2[pos + 1] = r1[pos] = 'X'
    elif pattern == 2:
        r1[pos] = r2[pos] = r2[pos + 1] = 'X'
    elif pattern == 3:
        r1[pos] = r1[pos + 1] = r2[pos + 1] = 'X'

r1 = list(row1)
r2 = list(row2)

count = 0
for i in range(n):
    for pattern in range(4):
        if can_place_bishwock(r1, r2, i, pattern):
            place_bishwock(r1, r2, i, pattern)
            count += 1
            break

print(count)
